[2828] = {
"Predaxas",
"Glutted on the writhing Voidstorm's spawn, Predaxas stalks the wilds hunting for prey. It does not rest, it does not reason, it devours with a hunger as insatiable as the dark.",
2828,
34925,
"|cff66bbff|Hjournal:1:2828:15|h[Predaxas]|h|r",
1312,
3431,
2930,
["n"] = 8,
},
[2782] = {
"Cragpine",
"Ancient as the cliffs themselves, Cragpine has slumbered for centuries beneath a canopy of towering pines. Now stirred by the careless intrusion of mortals, he rises to defend his glade, bending the forest itself to his will.",
2782,
32613,
"|cff66bbff|Hjournal:1:2782:15|h[Cragpine]|h|r",
